import React, { useState, useEffect } from "react";
import { CommentExtractor } from "./commentExtractor";
import { CommandInterpreter } from "./commandInterpreter";
import { OperationParser } from "./parseOperations";
import { evaluateOperations } from "./evaluateOperations";
import { OperationProcessor } from "./calculations";
import ReportGenerator from "./reportGenerator";
import { DotGenerator } from "./dotGenerator";
import { generateErrorReport } from "./errorReportGenerator";

class FileHandler {
  static openFile(event, setFileContent, setFileName) {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target.result;
        setFileContent(content);
      };
      reader.readAsText(file);
      setFileName(file.name);
    }
  }

  static saveFile(fileContent, fileName) {
    const blob = new Blob([fileContent], { type: "text/plain" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = fileName;
    link.click();
  }

  static saveFileAs(fileContent, fileName, setFileName) {
    const newFileName = prompt("Enter a new file name:", fileName);
    if (newFileName) {
      FileHandler.saveFile(fileContent, newFileName);
      setFileName(newFileName);
    }
  }
}

class ConsoleHandler {
  static overrideConsole(setConsoleLogs) {
    const originalConsoleLog = console.log;
    const originalConsoleError = console.error;

    console.log = (...args) => {
      originalConsoleLog(...args);
      setConsoleLogs((prevLogs) => [
        ...prevLogs,
        { type: "log", message: args.join(" ") },
      ]);
    };

    console.error = (...args) => {
      originalConsoleError(...args);
      setConsoleLogs((prevLogs) => [
        ...prevLogs,
        { type: "error", message: args.join(" ") },
      ]);
    };

    return () => {
      console.log = originalConsoleLog;
      console.error = originalConsoleError;
    };
  }

  static clearConsole(setConsoleLogs) {
    setConsoleLogs([]);
  }
}

class Analyzer {
  constructor(fileContent, determinarTipo) {
    this.fileContent = fileContent;
    this.determinarTipo = determinarTipo;
  }

  analyzeComments() {
    const extractor = new CommentExtractor(this.fileContent);
    const comments = extractor.extract();
    comments.forEach((comment) => {
      const prefix = comment.type === "single" ? "Comentario simple:" : "Comentario múltiple:";
      console.log(`${prefix} ${comment.text}`);
    });
  }

  analyzeErrors() {
    const errors = [];
    const lines = this.fileContent.split("\n");

    lines.forEach((line, rowIndex) => {
      [...line].forEach((char, colIndex) => {
        const tipo = this.determinarTipo(char);
        if (tipo === "Error léxico") {
          errors.push({
            token: char,
            type: tipo,
            row: rowIndex + 1,
            column: colIndex + 1,
          });
        }
      });
    });

    return errors;
  }

  analyze() {
    this.analyzeComments();

    const parser = new OperationParser(this.fileContent);
    const operations = parser.parse();

    const processor = new OperationProcessor(operations);

    console.log(`Total de operaciones principales: ${processor.conteo()}`);
    console.log(`Promedio de operaciones 'suma': ${processor.promedio("suma")}`);
    console.log(`Máximo de operaciones 'multiplicacion': ${processor.max("multiplicacion")}`);
    console.log(`Mínimo de operaciones 'raiz': ${processor.min("raiz")}`);

    evaluateOperations(operations);

    const interpreter = new CommandInterpreter(this.fileContent);
    interpreter.interpret();

    if (this.fileContent.includes("generarReporte(\"tokens\")")) {
      console.log("Detectado generarReporte(\"tokens\"), generando reporte...");
      const reportGenerator = new ReportGenerator(this.fileContent, this.determinarTipo);
      reportGenerator.generarReporte();
    }

    if (this.fileContent.includes("generarReporte(\"errores\"")) {
      const reportNameMatch = this.fileContent.match(/generarReporte\("errores",\s*"(.*?)"\)/);
      const reportName = reportNameMatch ? reportNameMatch[1] : "errores_reporte";
      const errors = this.analyzeErrors();
      if (errors.length > 0) {
        console.log(`Errores encontrados: ${errors.length}`);
        generateErrorReport(errors, reportName);
      } else {
        console.log("No se encontraron errores léxicos.");
      }
    }

    const dotGenerator = new DotGenerator(this.fileContent);
    const dotContent = dotGenerator.generate();
    DotGenerator.save(dotContent);
  }
}

function FileEditor() {
  const [fileContent, setFileContent] = useState("");
  const [fileName, setFileName] = useState("untitled.nlex");
  const [consoleLogs, setConsoleLogs] = useState([]);

  useEffect(() => {
    return ConsoleHandler.overrideConsole(setConsoleLogs);
  }, []);

  const determinarTipo = (char) => {
    if (/[a-zA-Z]/.test(char)) return "Identificador";
    if (/\d/.test(char)) return "Número";
    if (/[{}[\]()]/.test(char)) {
      if (char === "(") return "Paréntesis de apertura";
      if (char === ")") return "Paréntesis de cierre";
      if (char === "{") return "Llave de apertura";
      if (char === "}") return "Llave de cierre";
      return "Paréntesis o Llave";
    }
    if (/["]/.test(char)) return "Comilla";
    if (/[,]/.test(char)) return "IdentificadorComa";
    if (/\b(if|else|while|for|return)\b/.test(char)) return "Palabra reservada";
    if (/\s/.test(char)) return null;
    if (/[-+*/^]/.test(char)) return "Operador";
    return "Error léxico";
  };

  return (
    <div style={{ display: "flex", gap: "20px", padding: "20px", fontFamily: "'Arial', sans-serif" }}>
      <div
        style={{
          flex: 1,
          padding: "20px",
          backgroundColor: "#000",
          color: "#fff",
          borderRadius: "8px",
          boxShadow: "0 4px 8px rgba(0, 0, 0, 0.1)",
        }}
      >
        <h1 style={{ fontSize: "1.8rem", color: "#fff", marginBottom: "20px" }}>File Editor</h1>
        <div style={{ marginBottom: "20px", display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <button
            style={buttonStyle}
            onClick={() => document.getElementById("fileInput").click()}
          >
            Open File
          </button>
          <input
            id="fileInput"
            type="file"
            accept=".nlex"
            style={{ display: "none" }}
            onChange={(e) => FileHandler.openFile(e, setFileContent, setFileName)}
          />
          <button
            style={buttonStyle}
            onClick={() => FileHandler.saveFile(fileContent, fileName)}
          >
            Save
          </button>
          <button
            style={buttonStyle}
            onClick={() => FileHandler.saveFileAs(fileContent, fileName, setFileName)}
          >
            Save As
          </button>
          <button
            style={buttonStyle}
            onClick={() => {
              const reportGenerator = new ReportGenerator(fileContent, determinarTipo);
              reportGenerator.generarReporte();
            }}
          >
            Generate Report
          </button>
          <button
            style={buttonStyle}
            onClick={() => {
              const analyzer = new Analyzer(fileContent, determinarTipo);
              const errors = analyzer.analyzeErrors();
              if (errors.length > 0) {
                console.log(`Errores encontrados: ${errors.length}`);
                generateErrorReport(errors, "202300458_error");
              } else {
                console.log("No se encontraron errores léxicos.");
              }
            }}
          >
            Generate Errors
          </button>
          <button
            style={buttonStyle}
            onClick={() => {
              const analyzer = new Analyzer(fileContent, determinarTipo);
              analyzer.analyze();
            }}
          >
            Analyze
          </button>
          <button
            style={buttonStyle}
            onClick={() => ConsoleHandler.clearConsole(setConsoleLogs)}
          >
            Clear Console
          </button>
        </div>
        <textarea
          value={fileContent}
          onChange={(e) => setFileContent(e.target.value)}
          style={textareaStyle}
        />
      </div>
      <div style={consoleStyle}>
        <h2 style={{ fontSize: "1.6rem", color: "#fff", marginBottom: "20px" }}>Console</h2>
        <div>
          {consoleLogs.map((log, index) => (
            <div
              key={index}
              style={{
                padding: "10px",
                marginBottom: "10px",
                borderRadius: "4px",
                backgroundColor: log.type === "error" ? "#721c24" : "#155724",
                color: "#fff",
              }}
            >
              {log.message}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const buttonStyle = {
  backgroundColor: "#007bff",
  color: "white",
  border: "none",
  padding: "10px 20px",
  borderRadius: "4px",
  cursor: "pointer",
  transition: "background-color 0.3s ease",
};

const textareaStyle = {
  width: "100%",
  height: "300px",
  fontFamily: "'Monospace', sans-serif",
  padding: "10px",
  border: "1px solid #ccc",
  borderRadius: "4px",
  backgroundColor: "#333",
  color: "#fff",
  resize: "none",
};

const consoleStyle = {
  flex: 1,
  borderLeft: "1px solid #ccc",
  padding: "20px",
  backgroundColor: "#222",
  overflowY: "auto",
  borderRadius: "8px",
  height: "400px",
};

export default FileEditor;
